import{r as e}from"./_h-B_Y_XGdf.js";var t=[e(`oltp-point-select`,`OLTP point SELECT by primary key`,`OLTP`,`SELECT balance FROM accounts WHERE id = 42;`,`A cold simple-protocol query traced end to end through a disk-based row store (PostgreSQL/InnoDB-like): parse, bind against the catalog, estimate a 1-row result, choose an index scan, fetch the page through the buffer pool and stream the answer back. With a prepared statement the whole front half is skipped.`,[[`client>wire-protocol`,`Send Query message`,`Query "Q": SELECT balance FROM accounts WHERE id = 42`,`44 bytes of SQL in one TCP segment; client blocks for result.`],[`wire-protocol>connection-pool`,`Decode & route to session`,`session 17, COM_QUERY, autocommit=true`,`Framing decoded; session state (search_path, isolation) attached.`],[`connection-pool>lexer`,`SQL text to lexer`,`"SELECT balance FROM accounts WHERE id = 42"`,`Plan-cache miss for an unnamed statement, so the full front-end runs.`],[`lexer>parser`,`Token stream`,`[SELECT, IDENT balance, FROM, IDENT accounts, WHERE, IDENT id, =, INT 42]`,`One-token lookahead LALR pull.`],[`parser>ast`,`Build raw parse tree`,`SelectStmt{target:[balance], from:[accounts], where: id = 42}`,`Names unresolved, no types yet.`],[`ast>binder`,`Resolve names & types`,`ColumnRef(id) -> accounts.id int8 ; 42 -> int8`,`Needs a catalog snapshot.`],[`binder>catalog`,`Catalog lookup`,`lookup(table, "public.accounts")`,`Hits syscache; AccessShareLock taken on relation.`],[`catalog>binder`,`Table definition`,`oid=16403 cols=[id int8 PK, owner text, balance numeric(12,2)] indexes=[accounts_pkey] reltuples=100000`,`Schema version recorded for later revalidation.`],[`binder>logical-plan`,`Bound logical plan`,`Project[balance](Filter[id=42](Get accounts))`,`Typed and resolved.`],[`logical-plan>optimizer`,`Optimize`,`one relation: choose access path only`,`No join search needed; optimizer compares SeqScan vs IndexScan.`],[`optimizer>cardinality-estimator`,`Selectivity of id = 42`,`id is unique PK -> ndv=100000`,`Unique index implies exactly <=1 row.`],[`statistics>cardinality-estimator`,`n_distinct / MCV`,`pg_statistic: id n_distinct=-1 (all unique)`,`Stats read from relcache.`],[`cardinality-estimator>cost-model`,`1 row estimate`,`est_rows=1`,`Feeds both scan alternatives.`],[`cost-model>optimizer`,`Costs`,`SeqScan total=1280+1000*0.01=1290 ; IndexScan total=8.30`,`Index scan wins by ~150x.`],[`optimizer>physical-plan`,`Index Scan chosen`,`Index Scan using accounts_pkey on accounts (cost=0.29..8.30 rows=1 width=8)`,`Plan shape is a single node.`],[`physical-plan>executor`,`Start executor`,`ExecutorStart(IndexScan, snapshot{xmin:1001,xmax:1010})`,`Read-only statement: no xid assigned.`],[`executor>operators`,`Pull first tuple`,`IndexScan.next()`,`Volcano call.`],[`operators>access-method`,`Probe index`,`index_getnext(scankey id=42)`,``],[`access-method>btree`,`B-tree descent`,`root blk3 -> inner blk17 -> leaf blk204 -> TID (7,12)`,`3 page visits; root/inner likely cached.`],[`access-method>buffer-pool`,`Pin heap page`,`get_page(accounts, blk 7)`,`Miss: not in shared buffers.`],[`buffer-pool>file-manager`,`Read from disk`,`pread(fd, 8192 B, offset 57344)`,`~100 us NVMe, ~5 ms HDD.`],[`file-manager>buffer-pool`,`Page bytes`,`8192 B, checksum OK`,`Installed in frame 412, usage_count=1.`],[`buffer-pool>access-method`,`Pinned page`,`blk 7 pinned`,`Content shared-latched while reading tuple.`],[`access-method>heap-file`,`Fetch tuple & visibility check`,`TID (7,12) xmin=1001 committed < snapshot.xmax, xmax=0 -> visible`,`Hint bit may be set on tuple (dirtying page).`],[`access-method>operators`,`Return tuple`,`{id:42, balance:310.25}`,``],[`operators>executor`,`Project balance`,`310.25`,``],[`executor>wire-protocol`,`Encode result`,`RowDescription, DataRow("310.25"), CommandComplete "SELECT 1", ReadyForQuery`,`Streamed immediately.`],[`wire-protocol>client`,`Response bytes`,`44 00 00 00 0b 00 01 00 00 00 06 33 31 30 2e 32 35`,`Total server time ~0.1-0.3 ms when cached; dominated by planning for tiny queries.`]]),e(`oltp-update-commit`,`OLTP UPDATE with WAL commit`,`OLTP`,`BEGIN; UPDATE accounts SET balance = balance - 10 WHERE id = 42; COMMIT;`,`A write transaction under strict 2PL for writes + MVCC for reads: take intent and row locks, create a new tuple version, log physiologically to the WAL, flush the WAL once at commit (shared with concurrent committers through group commit), then release locks. The dirty data page is written later by the checkpointer.`,[[`client>wire-protocol`,`Send UPDATE (prepared)`,`Bind(S_2,[10,42]) Execute`,`Prepared/extended protocol: parameters separate from text.`],[`wire-protocol>connection-pool`,`Route`,`session 17 in transaction`,`BEGIN already issued.`],[`connection-pool>plan-cache`,`Lookup plan`,`S_2 -> HIT (generic plan)`,`No parse/plan cost.`],[`plan-cache>executor`,`Run cached plan`,`ModifyTable(Update) <- IndexScan(accounts_pkey)`,``],[`executor>txn-manager`,`Get/assign xid`,`xid=1011 assigned (first write)`,`Read-only txns would skip this.`],[`txn-manager>concurrency-control`,`Write intent`,`write(txn 1011, accounts#42)`,`MVCC reads, locked writes.`],[`concurrency-control>lock-manager`,`Row/table locks`,`accounts IX ; row (7,12) X`,`Intent then row lock; may wait on another writer.`],[`lock-manager>txn-manager`,`Granted`,`GRANTED waited_ms=0`,`If wait: worker sleeps; deadlock timeout starts.`],[`access-method>buffer-pool`,`Pin & X-latch page`,`blk 7 HIT, content lock EX`,`Page now cached and exclusively latched.`],[`concurrency-control>mvcc`,`Install version`,`first-updater-wins check: row not modified by newer committed txn`,`On conflict: wait or serialization error.`],[`mvcc>heap-file`,`New tuple version`,`old (7,12): xmax=1011, ctid->(7,31); new (7,31): xmin=1011 balance=300.25`,`Append-only MVCC; HOT chain since no indexed column changed.`],[`access-method>wal`,`Log the change`,`HEAP UPDATE lsn=0/3A8F1A0 xid=1011 old(7,12) new(7,31) len=52 (+FPI if first touch since checkpoint)`,`Page marked dirty with pageLSN=0/3A8F1A0.`],[`txn-manager>wal`,`COMMIT record`,`COMMIT xid=1011 lsn=0/3A8F2C0`,`Commit waits for flush to this LSN.`],[`wal>file-manager`,`fdatasync WAL`,`pwrite 8 KiB + fdatasync (~0.4 ms); batches 17 other committers`,`Group commit amortises the fsync; this is the durability point.`],[`txn-manager>lock-manager`,`Release locks`,`release_all(1011): row X, accounts IX`,`Waiters (e.g. txn 1013) can proceed.`],[`executor>wire-protocol`,`Reply`,`CommandComplete "UPDATE 1" ; ReadyForQuery`,`Ack only after durable commit (synchronous_commit=on).`],[`wire-protocol>client`,`Ack to client`,`UPDATE 1`,`Client latency ~ fsync + RTT.`],[`buffer-pool>wal`,`Later: checkpoint flush`,`page (16403,7) pageLSN=0/3A8F1A0 -> WAL already flushed`,`WAL-before-data rule; checkpointer writes dirty page in background.`],[`buffer-pool>file-manager`,`Write data page`,`pwrite(8192 B at 57344)`,`Random write deferred and coalesced - the point of WAL.`]]),e(`olap-scan-agg`,`OLAP columnar scan + aggregation`,`OLAP`,`SELECT region, SUM(amount) FROM sales WHERE ts >= DATE '2026-01-01' GROUP BY region;`,`A vectorized, morsel-driven engine (DuckDB/ClickHouse-like): optimizer builds one pipeline, zone maps prune row groups, only two columns are read, encoded chunks decode into vectors, SIMD filters and a per-thread hash aggregate run on morsels in parallel and are merged at the end.`,[[`client>wire-protocol`,`Send query`,`SELECT region, SUM(amount) …`,`Large result avoided: 50 groups.`],[`wire-protocol>connection-pool`,`Route`,`session 3`,``],[`connection-pool>lexer`,`Lex`,`SQL text`,``],[`lexer>parser`,`Tokens`,`…`,``],[`parser>ast`,`AST`,`SelectStmt with GROUP BY`,``],[`ast>binder`,`Bind`,`region:varchar, amount:decimal(18,2), ts:date`,``],[`binder>logical-plan`,`Logical plan`,`Aggregate[region; sum(amount)](Filter[ts>=…](Get sales))`,``],[`logical-plan>optimizer`,`Optimize`,`predicate pushdown into scan, projection prune to {region, amount, ts}`,`Pushdown makes zone-map pruning possible.`],[`statistics>cardinality-estimator`,`Table stats`,`sales: 1.2e9 rows, 9,766 row groups, ts min/max per group`,`Group cardinality ~50 (HLL).`],[`optimizer>physical-plan`,`Physical plan`,`HashAggregate <- TableScan(sales, filter ts>=…, cols=[region,amount])`,``],[`physical-plan>pipeline-dag`,`Pipelines`,`P1: Scan -> Filter -> HashAggregate(sink) ; P2: HashAggregate(source) -> Result`,`Aggregate finalize is the breaker.`],[`pipeline-dag>scheduler`,`Submit P1`,`9,766 row groups as morsels (122,880 rows each)`,``],[`scheduler>executor`,`Dispatch morsels`,`16 workers pull row groups from a shared atomic counter`,`Elastic: stragglers get fewer morsels.`,10],[`operators>access-method`,`Scan request`,`scan(cols=[region,amount,ts], pred ts>=2026-01-01)`,``],[`access-method>column-store`,`Zone-map check`,`rowgroups 9,766; min/max prune -> 1,210 survive`,`87% skipped with no data I/O (data clustered by ts).`],[`column-store>secondary-index`,`Min/max & bloom`,`ts max < 2026-01-01 -> skip`,`Metadata only.`],[`access-method>prefetcher`,`Hint sequential`,`next row groups 1,211..1,242`,``,11],[`prefetcher>buffer-pool`,`Async prefetch`,`read 3 column segments x 32 groups, io_depth 64`,``,11],[`column-store>buffer-pool`,`Read segments`,`region (dict, 0.1 B/row), amount (FOR+bitpack 14 bits), ts (delta)`,`Only 3 of 24 columns read.`,11],[`column-store>columnar-processing`,`Decode vectors`,`2,048-value vectors, region stays dictionary-encoded`,``],[`operators>columnar-processing`,`SIMD filter + hash agg`,`filter_ge(ts) -> selection vector 1,904/2,048 ; hash(region code) ; sum(amount)`,`Aggregate on dictionary codes = int hash.`],[`operators>executor`,`Thread-local partial results`,`16 partial hash tables x 50 groups`,``],[`executor>wire-protocol`,`Merged result`,`50 rows (region, sum)`,`Final merge combines partial aggregates.`],[`wire-protocol>client`,`Rows`,`North 18,402,113.50 ; …`,`~100-400 ms for 1.2e9-row table on 16 cores.`]]),e(`olap-join-shuffle`,`Distributed hash join with exchange`,`OLAP`,`SELECT c.region, SUM(o.total) FROM orders o JOIN customers c ON o.cust_id = c.id GROUP BY c.region;`,`MPP execution (StarRocks/Spark style): the coordinator fragments the plan; orders (1B rows) and customers (50M rows) are distributed by different keys so the optimizer inserts hash exchanges on the join key; build and probe sides stream to partitions, join locally, partial aggregate, and gather. Adaptive execution may re-plan on actual sizes.`,[[`client>wire-protocol`,`Submit query`,`SELECT … JOIN …`,``],[`wire-protocol>router-coordinator`,`Coordinator receives`,`FE/driver planning node`,``],[`logical-plan>optimizer`,`Logical plan`,`Aggregate(Join(orders, customers))`,``],[`sharding>optimizer`,`Distribution props`,`orders: HASH(id)x64 ; customers: HASH(id)x64 ; join key o.cust_id mismatches`,`Not colocated for orders.`],[`statistics>cardinality-estimator`,`Stats`,`orders 1e9 rows (58 GB), customers 5e7 rows (2.1 GB)`,`Customers (2.1 GB) exceeds the broadcast threshold, so a shuffle is required.`],[`optimizer>exchange-shuffle`,`Insert exchanges`,`Exchange[hash(o.cust_id)] on orders ; customers already HASH(id)=join key -> bucket shuffle only orders`,`Network cost model picks cheaper side.`],[`optimizer>physical-plan`,`Fragmented plan`,`F3: Gather; F2: HashAgg(partial) <- HashJoin(probe orders, build customers); F1: Scan orders -> Exchange(hash cust_id)`,``],[`physical-plan>pipeline-dag`,`Pipelines per fragment`,`build(customers) -> probe(orders) -> partial agg`,``],[`router-coordinator>executor`,`Ship fragments`,`F1 x64 instances, F2 x64 instances to 16 BEs`,`Each BE runs several fragment instances.`],[`operators>exchange-shuffle`,`Scan orders & partition`,`hash(cust_id) mod 64 -> 64 send buffers (4K rows each)`,`Serialised column batches, LZ4.`],[`exchange-shuffle>router-coordinator`,`Cross-node transfer`,`TransmitData(be-3:8060, f2, 1 MiB, LZ4, seq 812)`,`Network is the bottleneck: ~58 GB / 16 nodes ~ 3.6 GB per node.`],[`exchange-shuffle>operators`,`Receive partitions`,`recv 4096-row batches from 16 senders`,`Back-pressure if build not finished.`],[`operators>executor`,`Hash join + partial aggregate`,`build ht(customers 0.8M rows/part) ; probe 15.6M rows/part ; partial sum by region`,`Hash table fits 2 GB budget; else spills radix partitions.`],[`executor>adaptive-execution`,`Report stage stats`,`F1 output 57.9 GB actual vs 60 GB est`,``],[`adaptive-execution>optimizer`,`Re-plan check`,`estimates accurate; no change`,`If customers filtered to 8 MB: switch to broadcast join.`],[`adaptive-execution>scheduler`,`Coalesce/skew`,`partition 17 has 9x median -> split into 4 sub-tasks`,`Skew mitigation.`],[`executor>wire-protocol`,`Final merge`,`Gather partial aggregates -> 50 rows`,``],[`wire-protocol>client`,`Result`,`region,total rows`,``]]),e(`distributed-2pc-commit`,`Distributed two-phase commit`,`DISTRIBUTED`,`BEGIN; UPDATE acct SET bal=bal-100 WHERE id=1 /*shard -80*/; UPDATE acct SET bal=bal+100 WHERE id=2 /*shard 80-*/; COMMIT;`,`A transfer across two shards. The coordinator routes both statements, then at COMMIT runs 2PC: participants persist PREPARE (redo + locks held) and vote; the coordinator forces the decision record (the commit point) and sends COMMIT; participants commit, release locks and ack. A coordinator crash between phases leaves participants in doubt until recovery.`,[[`wire-protocol>router-coordinator`,`Statements arrive`,`UPDATE id=1 ; UPDATE id=2`,``],[`router-coordinator>sharding`,`Route`,`shard_for(1)`,``],[`sharding>router-coordinator`,`Shard map`,`id=1 -> -80 ; id=2 -> 80-`,`Two participants => needs 2PC.`],[`router-coordinator>distributed-commit`,`Begin global txn`,`gtid tx-9f2 participants [-80, 80-]`,``],[`logical-clocks>timestamp-oracle`,`Clock`,`HLC(wall=…, logical=0)`,``],[`distributed-commit>txn-manager`,`PREPARE (phase 1)`,`PREPARE tx-9f2 -> shard -80 and 80-`,``],[`txn-manager>wal`,`Persist prepare`,`PREPARE xid=77 gtid=tx-9f2 (forced, locks retained)`,`Participant can no longer unilaterally abort.`],[`txn-manager>distributed-commit`,`Vote YES`,`shard -80: YES lsn=0/3A9100 ; shard 80-: YES`,`Any NO or timeout => abort.`],[`timestamp-oracle>distributed-commit`,`Commit timestamp`,`commit_ts = max(prepare_ts)+1 = …134100`,`Gives consistent snapshot across shards.`],[`distributed-commit>wal`,`Force decision`,`COORD_COMMIT tx-9f2 [-80,80-]`,`Commit point of the global transaction.`],[`distributed-commit>txn-manager`,`COMMIT (phase 2)`,`COMMIT tx-9f2 -> participants`,``],[`txn-manager>wal`,`Local commit record`,`COMMIT xid=77`,``],[`txn-manager>lock-manager`,`Release locks`,`row locks released after commit`,`Locks were held across 2 round trips + 2 fsyncs.`],[`txn-manager>distributed-commit`,`Ack`,`committed`,``],[`router-coordinator>replication`,`Replicate (as needed)`,`shard-level replicas receive redo`,``]]),e(`raft-replicated-write`,`Raft-replicated write`,`DISTRIBUTED`,`UPDATE kv SET v = 290.25 WHERE k = 42;`,`A write on one Raft group (range/tablet) with RF=3: the leader appends to its log, replicates AppendEntries to followers in parallel, fsyncs, commits once a majority holds the entry, applies to the state machine, and replies. Latency = one round trip to the nearest majority + fsync.`,[[`wire-protocol>router-coordinator`,`Request`,`PUT k=42 v=290.25`,``],[`router-coordinator>sharding`,`Find range leader`,`range r17 [30..60)`,``],[`sharding>router-coordinator`,`Leader location`,`n1 (leader, term 7)`,`Stale cache => NotLeader redirect.`],[`router-coordinator>replication`,`Propose to leader`,`write(range r17)`,``],[`replication>consensus`,`Append`,`AppendEntries(term=7, prevLogIndex=18430, entries=[{18431 PUT}], leaderCommit=18430)`,`Sent to f1, f2 in parallel.`],[`consensus>wal`,`Persist log entry`,`fsync idx 18431 on leader and f1`,` Durable before ack (log is also the WAL).`],[`consensus>replication`,`Majority ack -> commit`,`acks leader+f1 (2/3) commitIndex=18431`,`f2 can lag or be down.`],[`replication>wal`,`Apply to state machine`,`apply idx 18431: k=42 -> 290.25`,``],[`replication>router-coordinator`,`Replica status`,`f2 lag 1 entry`,``]]),e(`crash-recovery-aries`,`Crash recovery (ARIES)`,`RECOVERY`,``,`After a power loss: the recovery manager scans the WAL from the last checkpoint. Analysis rebuilds the dirty page table and active transaction table; Redo repeats history for every logged change whose pageLSN is older than the record; Undo rolls back loser transactions, logging compensation records (CLRs). Then a checkpoint ends recovery.`,[[`wal>recovery`,`Analysis pass`,`from BEGIN_CKPT 0/3A8F100: ATT={1011 committed, 1013 active}, DPT={(16403,7)->0/3A8F168,(16403,9)->0/3A8F1A0}`,`Establishes redo start = min recLSN.`],[`wal>recovery`,`Redo scan`,`read records 0/3A8F168.. ; stop at first bad CRC`,``],[`file-manager>buffer-pool`,`Load page from disk`,`page (16403,7) on disk has pageLSN=0/3A8F0F0`,`Stale on-disk image.`],[`recovery>buffer-pool`,`Redo records`,`pageLSN 0/3A8F0F0 < rec 0/3A8F168 -> REDO ; page (16403,9) pageLSN 0/3A8F1A0 >= rec -> SKIP`,`Idempotent via pageLSN.`],[`recovery>txn-manager`,`Undo losers`,`txn 1013 had no COMMIT -> roll back via prevLSN chain`,``],[`recovery>wal`,`Write CLRs`,`CLR undoNextLSN=0/3A8F168 for each undone change`,`Crash during undo does not repeat work.`],[`buffer-pool>wal`,`WAL rule`,`log flushed before dirty pages written`,``],[`recovery>wal`,`End-of-recovery checkpoint`,`CHECKPOINT redo=0/3A9200`,`Next recovery starts here.`]]),e(`lsm-write-read-compact`,`LSM write, read and compaction`,`OLTP`,`PUT accounts/42 = 290.25; GET accounts/42; (background compaction)`,`In a RocksDB/Cassandra-style engine: a write goes to the WAL and the memtable (skiplist). When the memtable is full it is flushed as an immutable L0 SSTable. Reads check the memtable, then L0 files (bloom filters), then each level. Compaction merges overlapping files, dropping shadowed versions and expired tombstones while honouring open snapshots.`,[[`client>wire-protocol`,`Write request`,`PUT accounts/42 = 290.25`,``],[`access-method>lsm-tree`,`Write path`,`put(accounts/42, 290.25)`,``],[`lsm-tree>wal`,`Append to WAL`,`seq=9912 CRC len=44 [Put accounts/42 -> 290.25]`,`Durable (fsync if sync=true).`],[`lsm-tree>skiplist`,`Insert into memtable`,`key+seq in skiplist level 3; memtable 64 MiB full => switch`,`Immutable memtable queued for flush.`],[`mvcc>lsm-tree`,`Version as separate key`,`accounts/42 @ ts=812 ; older @ ts=790 remains`,`No in-place update: compaction must keep versions needed by snapshots.`],[`lsm-tree>compression`,`Flush: compress blocks`,`4 KiB blocks LZ4 ratio 1.8`,``],[`lsm-tree>file-manager`,`Flush to L0`,`000125.sst 63.8 MiB, 812K keys, bloom 10 bits/key, index block, footer`,`L0 files overlap in key range; WAL for flushed memtable deleted.`],[`access-method>lsm-tree`,`Read path`,`get(accounts/42): memtable miss -> L0: 000123.sst bloom no; 000125.sst bloom yes -> read; L1 bloom no`,`Bloom filters avoid ~99% of useless SST reads.`],[`lsm-tree>file-manager`,`Compaction merge`,`L0(4 files)+L1(6 overlapping) -> 7 new L1 files; drop versions older than oldest snapshot ts=800; drop tombstones only at bottom level`,`Write amplification ~10-30x for leveled.`]])];export{t as default};